import React from 'react';
import { useParams, Navigate } from 'react-router-dom';
import { useSEO } from '../../hooks/useSEO';
import { ARTICLES, getArticle } from '../../data/articles';
import { SectionDivider } from '../divider';
import { CtaCard } from '../shared/CtaCard';
import { BOT, getLink } from '../../constants';
import styles from './page-article.module.css';

const INLINE_RE = /(\*\*[^*]+\*\*|\[[^\]]+\]\([^)]+\))/g;

const renderInline = (text, keyPrefix) =>
  text
    .split(INLINE_RE)
    .filter(Boolean)
    .map((part, index) => {
      const key = `${keyPrefix}-${index}`;

      const boldMatch = part.match(/^\*\*([^*]+)\*\*$/);
      if (boldMatch) {
        return <strong key={key}>{boldMatch[1]}</strong>;
      }

      const linkMatch = part.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      if (linkMatch) {
        const href = linkMatch[2].replace(/^https?:\/\/masha-normalno\.ru/, '') || '/';
        return (
          <a key={key} href={href} className={styles.inlineLink}>
            {linkMatch[1]}
          </a>
        );
      }

      return <React.Fragment key={key}>{part}</React.Fragment>;
    });

const renderBlock = (block, index) => {
  switch (block.type) {
    case 'h2':
      return (
        <h2 key={index} className={styles.articleH2}>
          {renderInline(block.text, index)}
        </h2>
      );
    case 'h3':
      return (
        <h3 key={index} className={styles.articleH3}>
          {renderInline(block.text, index)}
        </h3>
      );
    case 'ol':
      return (
        <ol key={index} className={styles.articleList}>
          {block.items.map((item, itemIndex) => (
            <li key={itemIndex} className={styles.articleListItem}>
              {renderInline(item, `${index}-${itemIndex}`)}
            </li>
          ))}
        </ol>
      );
    case 'ul':
      return (
        <ul key={index} className={styles.articleList}>
          {block.items.map((item, itemIndex) => (
            <li key={itemIndex} className={styles.articleListItem}>
              {renderInline(item, `${index}-${itemIndex}`)}
            </li>
          ))}
        </ul>
      );
    default:
      return (
        <p key={index} className={styles.articleParagraph}>
          {renderInline(block.text, index)}
        </p>
      );
  }
};

export const PageArticle = () => {
  const { slug } = useParams();
  const article = getArticle(slug);

  const seo = article
    ? {
        title: `${article.seoTitle} — Нормальный книжный клуб`,
        description: article.description,
        openGraph: {
          title: `${article.seoTitle} — Нормальный книжный клуб`,
          description: article.description,
          type: 'article',
          url: `https://masha-normalno.ru/blog/${article.slug}`,
          image: 'https://masha-normalno.ru/og-image-club.png',
        },
        schemaLD: {
          "@context": "https://schema.org",
          "@type": "BlogPosting",
          "headline": article.h1,
          "description": article.description,
          "inLanguage": "ru-RU",
          "url": `https://masha-normalno.ru/blog/${article.slug}`,
          "mainEntityOfPage": `https://masha-normalno.ru/blog/${article.slug}`,
          "author": {
            "@type": "Person",
            "name": "Мария Бурлакова"
          },
          "publisher": {
            "@type": "Organization",
            "name": "Нормальный книжный клуб"
          }
        },
      }
    : {
        title: 'Статья не найдена — Нормальный книжный клуб',
        description: 'Запрашиваемая статья не найдена.',
        openGraph: {
          title: 'Статья не найдена — Нормальный книжный клуб',
          description: 'Запрашиваемая статья не найдена.',
          type: 'website',
          url: 'https://masha-normalno.ru/blog',
          image: 'https://masha-normalno.ru/og-image-club.png',
        },
      };

  useSEO(seo);

  if (!article) {
    return <Navigate to="/blog" replace />;
  }

  const related = ARTICLES.filter((item) => item.slug !== article.slug).slice(0, 3);

  return (
    <div className={styles.pageArticle}>
      <div className={styles.readingWrap}>
        <nav className={styles.breadcrumb} aria-label="Хлебные крошки">
          <a href="/blog" className={styles.breadcrumbLink}>Блог</a>
          <span className={styles.breadcrumbSeparator} aria-hidden="true">/</span>
          <span className={styles.breadcrumbCurrent}>{article.h1}</span>
        </nav>

        <article className={styles.article}>
          <h1 className={styles.articleTitle}>{article.h1}</h1>
          <div className={styles.articleContent}>
            {article.content.map(renderBlock)}
          </div>
        </article>
      </div>

      <SectionDivider />

      <CtaCard
        text="Хотите обсудить книгу вместе с другими?"
        buttonText="Telegram бот для записи"
        buttonHref={getLink(BOT.startProps.club)}
        buttonTarget="_blank"
        buttonRel="noopener noreferrer"
        accentColor="pink"
      />

      <SectionDivider />

      <section className={styles.related}>
        <h2 className={styles.relatedTitle}>Читайте также</h2>
        <div className={styles.relatedGrid}>
          {related.map((item) => (
            <a key={item.slug} href={`/blog/${item.slug}`} className={styles.relatedCard}>
              <span className={styles.relatedCardTitle}>{item.h1}</span>
              <span className={styles.relatedCardText}>{item.description}</span>
              <span className={styles.relatedCardArrow} aria-hidden="true">→</span>
            </a>
          ))}
        </div>
      </section>
    </div>
  );
};
